"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, List, Optional

from pydantic import BaseModel, ValidationError, field_validator


_DECIMAL_2 = Decimal("0.01")
_TOTAL_Q = Decimal("0.01")


def _to_utc_datetime(value: Any) -> datetime:
    """
    Parse an ISO-8601-ish datetime and return an aware UTC datetime.
    - If a naive datetime is provided, it's treated as UTC.
    - If a timezone-aware datetime is provided, it's converted to UTC.
    """
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        s = value.strip()
        # datetime.fromisoformat doesn't accept trailing 'Z' directly.
        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(s)
        except ValueError as e:
            raise ValueError("invalid issued_at datetime string") from e
    else:
        raise ValueError("issued_at must be an ISO 8601 string or datetime")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)

    return dt


def _parse_decimal_2dp(value: Any) -> Decimal:
    """
    Parse value into Decimal with validation that it is >= 0.
    Keep enough precision to later quantize to exactly 2 decimals for output.
    """
    try:
        # Avoid float->binary artifacts by going through str for floats.
        if isinstance(value, float):
            dec = Decimal(str(value))
        elif isinstance(value, int):
            dec = Decimal(value)
        elif isinstance(value, Decimal):
            dec = value
        elif isinstance(value, str):
            dec = Decimal(value)
        else:
            # Let Decimal handle other compatible types; otherwise fail.
            dec = Decimal(value)
    except (InvalidOperation, TypeError) as e:
        raise ValueError("unit_price must be a decimal number") from e

    if dec < 0:
        raise ValueError("unit_price must be >= 0")

    return dec


def _quantize_2dp(d: Decimal) -> Decimal:
    # Exactly two decimals.
    return d.quantize(_DECIMAL_2, rounding=ROUND_HALF_UP)


def _format_utc_z_seconds(dt: datetime) -> str:
    # Billing format: YYYY-MM-DDTHH:MM:SSZ (UTC, second precision).
    dt_utc = dt.astimezone(timezone.utc)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


class _LineIn(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @field_validator("sku")
    @classmethod
    def _validate_sku(cls, v: str) -> str:
        if not isinstance(v, str):
            raise ValueError("sku must be a string")
        return v

    @field_validator("quantity")
    @classmethod
    def _validate_quantity(cls, v: Any) -> int:
        # Let pydantic coerce ints from strings; then validate.
        if isinstance(v, bool):
            raise ValueError("quantity must be an integer >= 1")
        try:
            q = int(v)
        except (TypeError, ValueError) as e:
            raise ValueError("quantity must be an integer") from e
        if q < 1:
            raise ValueError("quantity must be >= 1")
        return q

    @field_validator("unit_price", mode="before")
    @classmethod
    def _validate_unit_price_before(cls, v: Any) -> Decimal:
        return _parse_decimal_2dp(v)

    @field_validator("unit_price")
    @classmethod
    def _validate_unit_price(cls, v: Decimal) -> Decimal:
        # Ensure it can be rounded to exactly 2dp deterministically.
        _ = _quantize_2dp(v)
        return v


class _InvoiceIn(BaseModel):
    number: str
    issued_at: datetime
    lines: List[_LineIn]

    @field_validator("number")
    @classmethod
    def _validate_number(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("number must be a string")
        return v

    @field_validator("issued_at", mode="before")
    @classmethod
    def _validate_issued_at_before(cls, v: Any) -> datetime:
        return _to_utc_datetime(v)

    @field_validator("lines")
    @classmethod
    def _validate_lines(cls, v: Any) -> List[_LineIn]:
        if not isinstance(v, list):
            raise ValueError("lines must be a list")
        if len(v) == 0:
            raise ValueError("lines must not be empty")
        return v


def export_invoice(data: dict) -> str:
    """
    Validate an invoice with pydantic and return JSON text for the billing API.

    Input:
      - number: str
      - issued_at: ISO 8601 string or datetime (naive treated as UTC)
      - lines: list of {sku: str, quantity: int>=1, unit_price: decimal >= 0 as str/int/float}
    Output JSON object:
      - number: original string
      - issued_at: 'YYYY-MM-DDTHH:MM:SSZ' in UTC
      - lines: [{sku, quantity, unit_price}] with unit_price as string with exactly two decimals
      - total: sum(quantity * unit_price) as string with exactly two decimals
    """
    try:
        inv = _InvoiceIn.model_validate(data)
    except ValidationError as e:
        raise ValueError("invalid invoice input") from e
    except ValueError as e:
        raise

    issued_at_z = _format_utc_z_seconds(inv.issued_at)

    out_lines: List[dict[str, Any]] = []
    total = Decimal("0")
    for line in inv.lines:
        unit_price_2dp = _quantize_2dp(line.unit_price)
        line_total = unit_price_2dp * Decimal(line.quantity)
        total += line_total
        out_lines.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": f"{unit_price_2dp:.2f}",
            }
        )

    total_2dp = _quantize_2dp(total)

    payload = {
        "number": inv.number,
        "issued_at": issued_at_z,
        "lines": out_lines,
        "total": f"{total_2dp:.2f}",
    }

    # Avoid pydantic json formatting; keep exact required string formatting.
    import json

    return json.dumps(payload, separators=(",", ":"), ensure_ascii=False)

from __future__ import annotations

from typing import Any, Optional

from pydantic import BaseModel, ValidationError, field_validator


class _ImportProfileRow(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @field_validator("display_name")
    @classmethod
    def _collapse_and_reject_blank(cls, v: Any) -> str:
        # Coerce to string using pydantic's parsing; after parsing, ensure whitespace rules.
        v = str(v)
        v = " ".join(v.split())
        if not v:
            raise ValueError("display_name must not be blank")
        return v

    @field_validator("zip_code", mode="before")
    @classmethod
    def _zip_as_string(cls, v: Any) -> str:
        # Accept string or integer (and other numeric-ish values pydantic can parse),
        # but store as a string.
        if v is None:
            raise ValueError("zip_code is required")
        return str(v)


def import_profiles(rows: list) -> list:
    """
    Validate profile rows (dicts) with a Pydantic model and return valid ones as dicts:
    {"user_id": int, "display_name": str, "bio": str or None, "zip_code": str}

    - Keeps input order
    - Silently skips invalid rows
    """
    out: list[dict[str, Any]] = []
    for row in rows:
        try:
            model = _ImportProfileRow.model_validate(row)
        except (ValidationError, ValueError, TypeError):
            continue
        out.append(
            {
                "user_id": model.user_id,
                "display_name": model.display_name,
                "bio": model.bio,
                "zip_code": model.zip_code,
            }
        )
    return out

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, Field, ValidationError, field_validator, model_validator


_USERNAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
_PHONE_COMPACT_RE = re.compile(r"^\+\d{8,15}$")


class _SignupModel(BaseModel):
    username: str = Field(...)
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @field_validator("username")
    @classmethod
    def _validate_username(cls, v: Any) -> str:
        if not isinstance(v, str) or _USERNAME_RE.fullmatch(v) is None:
            raise ValueError("invalid username")
        return v

    @field_validator("email")
    @classmethod
    def _validate_email(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("email must be a string")
        normalized = v.strip().lower()
        if "@" not in normalized:
            raise ValueError("invalid email")
        return normalized

    @field_validator("phone")
    @classmethod
    def _validate_phone(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("phone number must be a string")
        compact = re.sub(r"[\s.\-()]", "", v)
        if _PHONE_COMPACT_RE.fullmatch(compact) is None:
            raise ValueError("invalid phone number")
        return compact

    @model_validator(mode="after")
    def _check_passwords_match(self) -> "_SignupModel":
        if self.password != self.password_confirm:
            raise ValueError("passwords do not match")
        return self


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        ValueError (pydantic ValidationError) for any missing or invalid field.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    try:
        model = _SignupModel.model_validate(data)
    except ValidationError as e:
        # pydantic ValidationError is a subclass of ValueError in pydantic v2
        raise e

    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }
